/* 知夏 · 面板补图
 *
 * 作者那版面板里两张图写的是本地文件名（zhixia_rental_room.jpg / zhixia_character_art.jpg），
 * 放到 CDN 上取不到，页面会露两块空。这支脚本在页面加载后把图换成仓库里的地址。
 *
 * 两条路都走：
 * 1. 直接挂 `document.querySelectorAll('img')`，页面同源时能这么改。
 * 2. 面板被 `$('body').load()` 插进楼层之后，`<img>` 是酒馆父页面的节点，读不到 contentDocument，
 *    这时改用一次全局搜索，把 `src` 里还写着本地文件名的图换掉。
 *
 * 换图只改这两处地址，想换成别的图改下面的常量即可，不用动面板文件本身。
 */

const 仓库前缀 = 'https://cdn.jsdelivr.net/gh/Tellccm/Zhixia@main/dist/知夏/界面/作者版面板/';

const 图 = {
  'zhixia_rental_room.jpg': 仓库前缀 + 'zhixia_rental_room.png',
  'zhixia_character_art.jpg': 仓库前缀 + 'zhixia_character_art.png',
};

function 该换成什么(原地址: string): string | null {
  if (!原地址) return null;
  for (const [本地名, 网络地址] of Object.entries(图)) {
    if (原地址.includes(本地名)) return 网络地址;
  }
  return null;
}

/** 在一个文档里找图并替换。找不到就返回 0。 */
function 补文档(文档: Document) {
  let 改过 = 0;
  try {
    文档.querySelectorAll('img').forEach(节点 => {
      const 新址 = 该换成什么(节点.getAttribute('src') ?? '');
      if (新址) {
        节点.setAttribute('src', 新址);
        改过 += 1;
      }
    });
  } catch {
    // 跨域文档读不了，交给下面那一步
  }
  return 改过;
}

/** 从某个根节点开始，连影子树一起翻，找 iframe 里的文档。 */
function 扫节点(节点: Element | Document | ShadowRoot): number {
  let 改过 = 0;
  const 文档们: Document[] = [];
  try {
    if (节点 instanceof Document) 文档们.push(节点);
    const 框们 = (节点 as ParentNode).querySelectorAll?.('iframe') ?? [];
    框们.forEach(框 => {
      try {
        if (框.contentDocument) 文档们.push(框.contentDocument);
      } catch {
        // 跨域，跳过
      }
    });
  } catch {
    // 忽略
  }
  文档们.forEach(文档 => {
    改过 += 补文档(文档);
  });
  return 改过;
}

function 补一轮() {
  let 合计 = 扫节点(document);
  // 同源的 iframe 可能刚插进来还没渲染完，隔一会儿再补一次
  window.setTimeout(() => {
    扫节点(document);
  }, 800);
  return 合计;
}

$(() => {
  console.info('[面板补图] 挂上了');
  补一轮();

  // 面板是异步插进楼层的，所以多补几轮；用 MutationObserver 也有收益，但它对跨域 iframe 无能为力，
  // 这里就用几个定时点覆盖加载过程。
  [1200, 2500, 5000].forEach(延迟 => window.setTimeout(补一轮, 延迟));

  eventOn(tavern_events.CHARACTER_MESSAGE_RENDERED, () => window.setTimeout(补一轮, 600));
  eventOn(tavern_events.MESSAGE_UPDATED, () => window.setTimeout(补一轮, 600));
});
